/bin/bash -lc "python - <<'PY'
import json
x=json.load(open(\"canonical-input.json\"))
def walk(x,d=0):
 if d>2: return
 if isinstance(x,dict):
  for k,v in x.items():
   print(' '*d,k, type(v).__name__, str(len(v)) if hasattr(v,'__len__') else v)
   walk(v,d+1)
 elif isinstance(x,list) and x: walk(x[0],d+1)
walk(x)
PY"

