import json,difflib
x=json.load(open('canonical-input.json'))
o=x['original'];c=x['candidate']
def diff(a,b,p):
 if a==b:return
 if isinstance(a,dict) and isinstance(b,dict):
  for k in list(dict.fromkeys([*a,*b])): diff(a.get(k),b.get(k),p+'.'+k)
 elif isinstance(a,list) and isinstance(b,list) and len(a)==len(b):
  for i,(oa,cb) in enumerate(zip(a,b)):diff(oa,cb,p+f'[{i}]')
 elif not p.endswith('description') or p.endswith('[15].description'):print(p, str(a)[:120],'=>',str(b)[:90])
diff(o,c,'')
for k in ['solutionContent','solutionContentEn']:
 print('DIFF',k)
 for s in difflib.unified_diff(o['examData'][k].splitlines(),c['examData'][k].splitlines(),n=0):
  print(s)

